starter.css:
.slot {
  width: 500px; /* the checks change this width */
}
.session-card {
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-inline-start: 6px solid #cbd5e1;
  border-radius: 12px;
}
.session-card p, .session-card h3 { margin: 0; }
.time { color: #6b7280; }

@media (width >= 400px) {
  .session-card {
    display: grid;
    grid-template-columns: 6rem 1fr;
    gap: 1rem;
  }
}

solution.css:
.slot {
  width: 500px; /* the checks change this width */
}
.session-card {
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-inline-start: 6px solid #cbd5e1;
  border-radius: 12px;
}
.session-card p, .session-card h3 { margin: 0; }
.time { color: #6b7280; }

.slot {
  container: session / inline-size;
}

@container session (width >= 400px) {
  .session-card {
    display: grid;
    grid-template-columns: 6rem 1fr;
    gap: 1rem;
  }
}

@container style(--variant: featured) {
  .session-card {
    border-inline-start-color: #6d28d9;
  }
}
